    /// <summary>
    /// Gets the #GESBaseEffect-s that have been added to the clip. The
    /// returned list is ordered by their internal index in the clip. See
    /// ges_clip_get_top_effect_index().
    /// </summary>
    /// <returns>
    /// A list of all
    /// #GESBaseEffect-s that have been added to @clip.
    /// </returns>
    public System.Collections.Generic.IReadOnlyList<GES.TrackElement> GetTopEffects()
    {
        nint nativeResult = GesClipGetTopEffects(Handle);
        System.GC.KeepAlive(this);
        nint[] nativeItems = Gst.Interop.GListMarshal.CollectAndFreeSpine(nativeResult);
        System.Collections.Generic.List<GES.TrackElement> result = new(nativeItems.Length);
        foreach (nint nativeItem in nativeItems)
        {
            if (nativeItem != 0 && Gst.GObject.Object.FromNative<GES.TrackElement>(nativeItem, Gst.Interop.Transfer.Full) is { } adopted)
            {
                result.Add(adopted);
            }
        }

        return result;
    }

